SourceCode.Declaration:
/// <summary>
/// This class is used as helper class for METPalletRoundingPolicySearch class.
/// Post introduction of the Layer rounding policy as per SG-265743 of CB223 Pallet Rounding, 
/// created this class as helper since validation checks and rounding threshold check occuring intially in the METSalesLinePalletRoundingProcess is now required to be done during the search call itself.
/// Searching suitable policy type record, its validatons and threshold check is done in METPalletRoundingPolicySearch now.
/// </summary>
public final class METPalletRoundingPolicySearchResultantHelper
{
    private METPalletRoundingPolicyLine palletRoundingPolicyLine;
    private SalesQty salesLineRoundedSalesQty;
    private boolean hasInventOrderSetup;

}

Method.Source:
/// <summary>
/// Creating a object of class <c>METPalletRoundingPolicySearchResultantHelper</c>
/// </summary>
/// <returns>Object of class <c>METPalletRoundingPolicySearchResultantHelper</c></returns>
public static METPalletRoundingPolicySearchResultantHelper construct()
{
    return new METPalletRoundingPolicySearchResultantHelper();
}

/// <summary>
/// Parm method for rounding policy record.
/// </summary>
/// <param name = "_palletRoundingPolicyLine">Unique rounding policy record</param>
/// <returns>Unique rounding policy record buffer</returns>
final public METPalletRoundingPolicyLine parmMETPalletRoundingPolicyLine(METPalletRoundingPolicyLine _palletRoundingPolicyLine = palletRoundingPolicyLine)
{
    palletRoundingPolicyLine = _palletRoundingPolicyLine;
    return palletRoundingPolicyLine;
}

/// <summary>
/// Parm method for rounded sales quantity.
/// </summary>
/// <param name = "_salesLineRoundedSalesQty">Rounded sales quantity for sales line</param>
/// <returns>Rounded sales quantity for sales line based on rounding policy</returns>
final public SalesQty parmSalesLineRoundedSalesQty(SalesQty _salesLineRoundedSalesQty = salesLineRoundedSalesQty)
{
    salesLineRoundedSalesQty = _salesLineRoundedSalesQty;
    return salesLineRoundedSalesQty;
}

/// <summary>
/// Parm method for Invent Order setup is validated.
/// </summary>
/// <param name = "_salesLineRoundedSalesQty">Rounded sales quantity for sales line</param>
/// <returns>Rounded sales quantity for sales line based on rounding policy</returns>
final public SalesQty parmHasInventOrderSetup(boolean _hasInventOrderSetup = hasInventOrderSetup)
{
    hasInventOrderSetup = _hasInventOrderSetup;
    return hasInventOrderSetup;
}
